<?php require '../includes/layout.php'; require_role(['admin']); $d=db();$keys=['cafe_name','tagline','currency','payment_methods','tax_rate','service_rate'];
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$values=['cafe_name'=>trim($_POST['cafe_name']??''),'tagline'=>trim($_POST['tagline']??''),'currency'=>trim($_POST['currency']??'PHP'),'payment_methods'=>trim($_POST['payment_methods']??''),'tax_rate'=>max(0,min(100,(float)($_POST['tax_rate']??0))),'service_rate'=>max(0,min(100,(float)($_POST['service_rate']??0)))];if(!$values['cafe_name']||!$values['payment_methods']){flash('Café name and payment methods are required.','err');}else{foreach($values as $k=>$v)$d->prepare('INSERT INTO cafe_settings(k,v) VALUES(?,?) ON DUPLICATE KEY UPDATE v=VALUES(v)')->execute([$k,(string)$v]);log_act('cafe settings updated');flash('Settings saved.');}go('admin/settings.php');}
$s=$d->query('SELECT k,v FROM cafe_settings')->fetchAll(PDO::FETCH_KEY_PAIR);head('Settings');?><div class="mb-4"><p class="text-xs font-semibold uppercase tracking-[.2em] text-mute">Configuration</p><h1 class="text-2xl font-semibold mt-1">Café settings</h1><p class="text-sm text-mute mt-1">These values are used across the customer and checkout pages.</p></div>
